SELECT ?premier ?premierLabel WHERE {
  ?province rdfs:label "Northern Cape Province"@en ;
            wdt:P31 wd:Q43229 .
  ?province p:P352 ?statement .
  ?statement ps:P352 ?premier .
  ?statement pq:P580 ?start .
  ?statement pq:P582 ?end .
  FILTER (?start <= "2018-12-31"^^xsd:date && ?end >= "2018-01-01"^^xsd:date)
  OPTIONAL { ?premier rdfs:label ?premierLabel . FILTER (LANG(?premierLabel) = 'en') }
}

